// Wait 60 seconds for Apify to finish scraping
await new Promise(resolve => setTimeout(resolve, 60000));
return $input.all();

const stories = $input.all();
const results = [];

for (const item of stories) {
  const story = item.json;

  const imageUrl = story.displayUrl || (story.images && story.images[0]) || story.imageUrl || '';

  if (!imageUrl) continue;

  const caption = story.caption || story.text || story.alt || '';
  const timestamp = story.timestamp || story.takenAt || new Date().toISOString();
  const storyId = story.id || story.shortCode || story.pk || 'story_' + Date.now();

  results.push({
    json: {
      storyId,
      imageUrl,
      caption,
      timestamp,
      username: story.ownerUsername || story.username || 'ghaith_nutrition10.10',
      mediaType: story.type || story.productType || 'image',
      hasImage: true
    }
  });
}

return results;

const items = $input.all();
const stories = $('📋 Parse Story Data').all();
const results = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  const story = (stories[i] && stories[i].json) ? stories[i].json : {};

  let base64Image = null;
  let mimeType = 'image/jpeg';

  if (item.binary && item.binary.data) {
    try {
      const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
      if (buffer && buffer.length > 0) {
        base64Image = buffer.toString('base64');
      }
    } catch (e) {
      // Fallback if binary stored in memory
      if (typeof item.binary.data.data === 'string' && !item.binary.data.data.startsWith('filesystem')) {
        base64Image = item.binary.data.data;
      }
    }
    mimeType = item.binary.data.mimeType || 'image/jpeg';
  }

  const parts = [];

  // Add image if valid base64 (never send filesystem pointer to Gemini)
  if (base64Image && base64Image !== 'filesystem-v2') {
    parts.push({
      inlineData: {
        mimeType: mimeType,
        data: base64Image
      }
    });
  }

  const promptText = `You are an automated product extraction agent for GymPilot, an e-commerce fitness supplements marketplace in Tunisia.\nAnalyze this Instagram story image and caption from seller Ghaith Nutrition.\n\nCRITICAL RULES:\n1. Currency is Tunisian Dinar (TND).\n2. Categories must be EXACTLY ONE of:\n   - Whey Protein\n   - Creatine\n   - Mass Gainer\n   - Vitamins & Supplements\n   - Equipment & Tools\n   - Packs & Stacks\n3. Classification:\n   - If 2 or more products are bundled together at a package price => type = \"pack\"\n   - If single product => type = \"product\"\n   - If just gym motivation, personal story, workout video, meme, or advertisement with no product and no price => type = \"skip\"\n\nCaption: ${story.caption || 'None'}\n\nRespond strictly with a single JSON object (no markdown, no backticks):\n{\n  \"type\": \"product\" | \"pack\" | \"skip\",\n  \"name\": \"Name of product or pack in French\",\n  \"description\": \"Clean description in French highlighting benefits and dosage\",\n  \"category\": \"one of the exact categories above\",\n  \"price\": 149.0,\n  \"originalPrice\": null,\n  \"tagline\": \"Short punchy tagline in French (only for packs)\",\n  \"badge\": \"NEW or PROMO or FLASH SALE\",\n  \"items\": [{\"name\": \"Product 1\", \"quantity\": 1}]\n}`;

  parts.push({ text: promptText });

  results.push({
    json: {
      geminiPayload: {
        contents: [{ parts }],
        generationConfig: {
          temperature: 0.1,
          maxOutputTokens: 1000,
          responseMimeType: 'application/json'
        }
      }
    }
  });
}

return results;

const items = $input.all();
const stories = $('📋 Parse Story Data').all();
const results = [];

const CATEGORY_MAP = {
  'whey protein': '6a985c4550777d3e0a93e601',
  'creatine': '6a985c4550777d3e0a93e602',
  'mass gainer': '6a985c4550777d3e0a93e603',
  'vitamins & supplements': '6a985c4550777d3e0a93e604',
  'vitamins': '6a985c4550777d3e0a93e604',
  'supplements': '6a985c4550777d3e0a93e604',
  'equipment & tools': '6a985c4550777d3e0a93e605',
  'equipment': '6a985c4550777d3e0a93e605',
  'packs & stacks': '6aa3cf01ae84ed74b697583f',
  'pack': '6aa3cf01ae84ed74b697583f'
};

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  try {
    const rawContent = item.json.candidates?.[0]?.content?.parts?.[0]?.text || '{}';
    const cleaned = rawContent.replace(/```json\n?/gi, '').replace(/```\n?/g, '').trim();
    const parsed = JSON.parse(cleaned);

    const storyData = (stories[i] && stories[i].json) ? stories[i].json : {};
    const catKey = (parsed.category || '').toLowerCase().trim();
    const resolvedCatId = CATEGORY_MAP[catKey] || '6a985c4550777d3e0a93e603';

    results.push({
      json: {
        ...parsed,
        categoryId: resolvedCatId,
        storyId: storyData.storyId || 'story_' + Date.now(),
        imageUrl: storyData.imageUrl || '',
        caption: storyData.caption || ''
      }
    });
  } catch (e) {
    results.push({
      json: {
        type: 'skip',
        error: 'Failed to parse Gemini response: ' + e.message
      }
    });
  }
}

return results;

const items = $input.all();
const results = [];

for (const item of items) {
  const data = item.json;
  const name = data.name || data.id || 'Unknown';

  results.push({
    json: {
      success: true,
      message: 'Successfully created in GymPilot for Ghaith Nutrition: ' + name,
      productId: data.id || data._id || 'N/A',
      timestamp: new Date().toISOString()
    }
  });
}

return results;

const body = $input.first().json.body || $input.first().json;

const CATEGORY_MAP = {
  'whey protein': '6a985c4550777d3e0a93e601',
  'creatine': '6a985c4550777d3e0a93e602',
  'mass gainer': '6a985c4550777d3e0a93e603',
  'vitamins & supplements': '6a985c4550777d3e0a93e604',
  'vitamins': '6a985c4550777d3e0a93e604',
  'supplements': '6a985c4550777d3e0a93e604',
  'equipment & tools': '6a985c4550777d3e0a93e605',
  'equipment': '6a985c4550777d3e0a93e605',
  'packs & stacks': '6aa3cf01ae84ed74b697583f',
  'pack': '6aa3cf01ae84ed74b697583f'
};

const type = body.type || 'product';
const name = body.name;
const price = body.price || 0;
const originalPrice = body.originalPrice || null;
const description = body.description || name + ' - Produit officiel Ghaith Nutrition disponible sur GymPilot.';
const category = body.category || 'Whey Protein';
const categoryId = CATEGORY_MAP[(category || '').toLowerCase().trim()] || '6a985c4550777d3e0a93e603';
const imageUrl = body.imageUrl || body.image || '';
const tagline = body.tagline || 'Offre speciale Ghaith Nutrition';
const badge = body.badge || 'NEW';
const items = body.items || [{ name: name, quantity: 1 }];

if (!name) {
  throw new Error('Missing required field: name');
}

return [{
  json: {
    type,
    name,
    price,
    originalPrice,
    description,
    category,
    categoryId,
    imageUrl,
    tagline,
    badge,
    items
  }
}];

